-- challenge chal_quiz_qaf_111 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qaf_111', (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qaf-1-1' AND is_deleted = false LIMIT 1), 'pyramid-and-trophy-quiz', 'Which level should catch this bug?', 'Two decisions from the checkout team''s test plan: where one bug should be caught, and what the pyramid and the trophy really say about end-to-end tests.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_111'), 'The order-history page must list a customer''s orders newest first. The repository builds the query like this:

// src/orders.repository.js
export async function listOrders(db, customerId) {
  return db.query(
    ''SELECT id, total_cents, created_at FROM orders WHERE customer_id = $1 ORDER BY created_at'',
    [customerId]
  );
}

ORDER BY created_at sorts oldest first. What is the LOWEST test level that can reliably catch this bug?', 'single_choice'::question_type, 'Integration is right: the bug is in what the database does with the SQL, so a test must run the real query against a real (or local test) database with two or three orders and check their order. A static check (linter, type checker) only sees a valid string and a valid function; it knows nothing about the ''newest first'' rule or what ORDER BY means. A unit test with a mocked db cannot catch it either: the mock returns whatever rows the test gives it, in whatever order, so the test checks the mock instead of the query. An end-to-end test through the browser would catch it, but it is not the lowest level: it needs the whole product running, takes seconds, and when it fails it points at a page, not at the query.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Static checks: a linter or type checker reading orders.repository.js', false),
        ('A unit test of listOrders with a mocked db whose query() returns three rows', false),
        ('An integration test that runs listOrders against a test database containing a few orders', true),
        ('An end-to-end test that logs in through the browser and reads the order-history page', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_111'), 'The team is redesigning the checkout suite that missed the VAT bug (about 180 browser tests, 42 minutes, red in about 6% of runs for unrelated reasons). Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'True: both the pyramid (Mike Cohn) and the trophy (Kent C. Dodds) keep end-to-end tests to a small top layer; they disagree on whether unit or integration tests form the bulk. True: a test that fails often for reasons unrelated to the change teaches people to ignore red, so a real failure is ignored too - that is what happened with the nightly report. False: the trophy still has a unit layer (and a static base); it only says integration tests should be the largest layer. False: e2e tests are slower and flakier because of what they run - a browser, servers, a database, the network and third-party pages - not only because of how they are written. Good selectors reduce flakiness but cannot make a multi-second browser journey as fast or as stable as a function call.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Both the test pyramid and the testing trophy keep end-to-end tests to a small layer at the top.', true),
        ('The testing trophy says to replace unit tests with integration tests completely.', false),
        ('A test that is red in about 6% of runs for unrelated reasons can do harm: people learn to ignore red, including real failures.', true),
        ('End-to-end tests are only slow and flaky when they are written badly; with good selectors they are as fast and stable as unit tests.', false)
    ) AS o(option_text, is_correct);

