-- challenge chal_quiz_qaf_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qaf_211', (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qaf-2-1' AND is_deleted = false LIMIT 1), 'picking-the-right-double-quiz', 'Pick the double, spot the over-specification', 'Four scenarios from the shop''s test suites and one test of placeOrder. Decide which double fits each job, and which assertion will break on a harmless refactor.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_211'), 'Which of these pairings of scenario and test double are good choices? (Select all that apply.)', 'multiple_choice'::question_type, 'A dummy is right when a collaborator is required by the constructor but never used on the path under test: the coupon path never touches the logger, so {} is enough (and a crash would tell you the assumption is wrong). A stub is right when the code needs an answer from a collaborator: the tax rate is an input, and the test checks the resulting total (state verification). The stub mailer is wrong: it always resolves, so it cannot tell whether an email was sent, how many, or to whom, and it can never fail - which is exactly how the password-reset outage went unnoticed. Use a spy or a fake mailer with an outbox, and a double that rejects to test the outage path. Replacing a method of the payment provider''s SDK in every checkout test is wrong: you do not own that interface, your double encodes your guess of how it behaves, and every checkout test is coupled to the SDK''s shape. Wrap the SDK in a small payments adapter you own, fake the adapter in checkout tests, and test the adapter itself in a few tests against the provider''s sandbox.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Testing that a coupon gives 10% off. The cart service requires a logger, but the coupon path never calls it: pass a dummy {}.', true),
        ('Testing the order total for a German customer: stub the tax service so taxRate("DE") resolves to 19, then assert the total in cents.', true),
        ('Testing that a password-reset email is sent exactly once: a stub mailer whose send() always resolves, then assert requestReset returned { status: "email sent" }.', false),
        ('Testing checkout payments: in every checkout test, replace the provider SDK''s client.charges.create with t.mock.method and assert the exact SDK request object.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_211'), 'A test of placeOrder(cart) uses an in-memory order store, a fake mailer with an outbox, a spy for the payments adapter and a spy for the internal price cache. It ends with four assertions:

// A
assert.strictEqual(order.totalCents, 5998);
// B
assert.deepStrictEqual(mailer.outbox.map((m) => m.template), ["order-confirmation"]);
// C
assert.deepStrictEqual(payments.charge.mock.calls.map((c) => c.arguments), [[order.id, 5998]]);
// D
assert.strictEqual(priceCache.get.mock.callCount(), 2);

A teammate changes placeOrder to look up both prices with one priceCache.getMany() call. Customers see no difference. Which assertion is over-specified and will break for no good reason?', 'single_choice'::question_type, 'D is over-specified: how many times placeOrder reads its own price cache is an implementation detail no customer can observe, so a harmless refactor (one batched lookup instead of two single ones) turns it red. A checks state - the outcome the customer pays - and survives any refactor that keeps the price right. B checks the outbox of a fake mailer: the confirmation email is a real outcome, and checking the template list (not the internal call sequence) leaves the service free to build the email however it likes. C is interaction verification, but here the interaction IS the outcome: charging the card exactly once with the right amount is the business rule, so counting the calls to the payments adapter is correct.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('D - the number of price-cache reads is an internal detail; the batched lookup changes it while the order stays the same.', true),
        ('A - asserting the exact total couples the test to the pricing code.', false),
        ('B - tests should never look at emails, only at return values.', false),
        ('C - verifying calls to any double is always over-specification; the charge should not be checked.', false)
    ) AS o(option_text, is_correct);

