-- challenge chal_quiz_qaf_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qaf_311', (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qaf-3-1' AND is_deleted = false LIMIT 1), 'flaky-test-causes-quiz', 'Why is it flaky, and what do you do about it?', 'Two situations from the shop''s CI. Decide which tests can change their result without a code change, and how a team should respond to a test that fails 1 run in 20.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_311'), 'Which of these tests can pass on one run and fail on the next, with exactly the same code? (Select all that apply.)

A)
test(''a random product gets free shipping'', () => {
  const product = products[Math.floor(Math.random() * products.length)];
  assert.equal(shippingCents(product), 0);
});
// one of the 12 fixture products is oversized and always pays shipping

B)
test(''sends the order confirmation'', async () => {
  placeOrder(order);                        // not awaited; it calls the staging mail API
  await new Promise((r) => setTimeout(r, 200));
  assert.equal(mailbox.sent.length, 1);
});

C)
beforeEach(() => { cart = createCart(); });
test(''SAVE10 expires after its last second'', (t) => {
  t.mock.timers.enable({ apis: [''Date''], now: new Date(''2026-11-01T00:00:00.000Z'') });
  assert.equal(isCouponValid(save10, cart), false);
});

D)
test(''formats 1999 cents'', () => {
  assert.equal(formatPrice(1999), ''$19.99'');   // formatPrice is a pure function
});', 'multiple_choice'::question_type, 'A is flaky through randomness: the test passes for 11 of the 12 products and fails whenever Math.random() picks the oversized one - with nothing logged, nobody can replay the failing input. Use fixed inputs, or inject a seeded random function and print the seed. B is flaky in two ways: it races a fixed 200 ms sleep against a real network call to the staging mail API, which is sometimes slower than 200 ms (and sometimes down). Await the promise placeOrder returns and use a fake mailer in a unit test. C is deterministic: the cart is fresh for every test and the time is pinned to an exact instant with t.mock.timers, so it gives the same result on every run, in every order and time zone. D is deterministic too: a pure function with fixed input has nothing that can change between runs (it can still be wrong, but it is wrong every time).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A - it picks a random product from the fixtures.', true),
        ('B - it waits 200 ms for a real call to the staging mail API.', true),
        ('C - it pins the time with t.mock.timers and creates a fresh cart in beforeEach.', false),
        ('D - it checks a pure function with a fixed input.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_311'), 'The test "applies the loyalty discount at checkout" fails about 1 run in 20 in CI. Nobody knows why yet, and it is blocking other teams'' merges. Which response is right?', 'single_choice'::question_type, 'Quarantine is a legitimate short-term move: it stops one unexplained test from blocking everyone, but only with an owner, a ticket that holds the failure logs (and seed, if any) and a deadline, and only while the test keeps running somewhere you can see its results - otherwise it is just a slow way to delete it. The owner then finds the cause (shared state, time, randomness, an async wait, an external service) or the bug in the code, as in this lesson''s incident. Turning on retries makes CI green without explaining anything: a real bug that fails 1 run in 20 is hidden just as well as a test bug. Deleting the test throws away the check and whatever it was trying to tell you. A longer sleep or timeout only changes how often a race loses; it makes the suite slower and the failure rarer and harder to reproduce.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Move it to a non-blocking job with a named owner, a ticket with the failing logs and a deadline; find and fix the cause before the deadline.', true),
        ('Configure CI to retry failed tests 3 times: if a retry passes, the code is fine.', false),
        ('Delete the test: a test that fails randomly gives no information.', false),
        ('Add await sleep(500) before the assertion and raise the test timeout, so slow CI runners have enough time.', false)
    ) AS o(option_text, is_correct);

