-- challenge chal_coding_qaf_321 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_qaf_321', (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qaf-3-2' AND is_deleted = false LIMIT 1), 'normalize-for-snapshot', 'Make the invoice snapshot deterministic', 'The invoice snapshot changes on every run: fresh UUIDs, a new createdAt and a key order that depends on how the object was merged. Write normalizeForSnapshot(value): it returns a new deep copy with object keys sorted at every depth, ISO-8601 timestamps replaced by "<timestamp>" and UUIDs replaced by "<id-1>", "<id-2>", ... numbered by first appearance, so the same id always gets the same placeholder. Two runs of the same invoice must then produce the same snapshot, while a missing VAT line still shows up as a difference.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
