VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qaf_321'), 'Sorts object keys at every depth, including objects inside arrays', '{"check":"value","value":{"total":2750,"customer":{"name":"Nguyen An","country":"VN"},"lines":[{"sku":"MUG-01","qty":2}]}}', '"{\"customer\":{\"country\":\"VN\",\"name\":\"Nguyen An\"},\"lines\":[{\"qty\":2,\"sku\":\"MUG-01\"}],\"total\":2750}"', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qaf_321'), 'Replaces whole-string ISO-8601 timestamps and keeps every other value', '{"check":"value","value":{"status":"paid","createdAt":"2026-10-21T09:19:24.446Z","paidAt":"2026-10-21T16:19:24+07:00","dueDate":"2026-11-20","note":"paid at 2026-10-21T09:19:24Z","shippedAt":null,"paid":true}}', '"{\"createdAt\":\"<timestamp>\",\"dueDate\":\"2026-11-20\",\"note\":\"paid at 2026-10-21T09:19:24Z\",\"paid\":true,\"paidAt\":\"<timestamp>\",\"shippedAt\":null,\"status\":\"paid\"}"', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qaf_321'), 'Numbers UUIDs by first appearance (sorted keys) and keeps references to the same id', '{"check":"value","value":{"invoiceId":"0b6e5f6a-58f1-4c1e-9d1a-6f2a1c9e7b10","lines":[{"id":"3c2d1e0f-4a5b-4c6d-8e7f-901a2b3c4d5e","sku":"MUG-01"},{"id":"a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d","sku":"TEE-02"}],"discounts":[{"appliesTo":"a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d","amountCents":300}]}}', '"{\"discounts\":[{\"amountCents\":300,\"appliesTo\":\"<id-1>\"}],\"invoiceId\":\"<id-2>\",\"lines\":[{\"id\":\"<id-3>\",\"sku\":\"MUG-01\"},{\"id\":\"<id-1>\",\"sku\":\"TEE-02\"}]}"', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qaf_321'), 'Leaves the input untouched and returns a new copy', '{"check":"mutation","value":{"invoiceId":"0b6e5f6a-58f1-4c1e-9d1a-6f2a1c9e7b10","createdAt":"2026-10-21T09:19:24.446Z","lines":[{"sku":"MUG-01","id":"3c2d1e0f-4a5b-4c6d-8e7f-901a2b3c4d5e","qty":2}],"customer":{"name":"Nguyen An","country":"VN"}}}', '"input unchanged, new copy"', 5, true, false, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qaf_321'), 'The incident: two runs of one invoice snapshot the same, a missing VAT line does not', '{"check":"incident"}', '{"sameInvoiceTwoRuns":"identical","missingVatLine":"differs"}', 5, true, false, 5),
