-- challenge chal_quiz_qaf_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qaf_331', (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'test-automation-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qaf-3-3' AND is_deleted = false LIMIT 1), 'coverage-vs-mutation-quiz', 'What do coverage and mutation score really say?', 'Compute a mutation score from a real-looking report, and decide which claims about node:test coverage are true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_331'), 'A mutation run on src/coupons.js produced this report:

  mutants generated   20
  killed              14
  survived             6

The team reviewed the 6 survivors. Two of them change i < items.length to i !== items.length in a loop where i starts at 0 and goes up by 1 - they behave exactly like the original for every input. The other 4 are real gaps. What is the mutation score?', 'single_choice'::question_type, 'Mutation score = killed / (total - equivalent). The two loop mutants are equivalent: no test can ever kill them, so they are removed from the denominator instead of being counted as failures or as successes. 14 / (20 - 2) = 14 / 18 = 77.8%. 70% (14 / 20) treats the equivalent mutants as gaps the suite should have caught, which punishes the team for something no test can do. 80% ((14 + 2) / 20) and 88.9% ((14 + 2) / 18) count the equivalent mutants as killed, which inflates the score: nothing in the suite actually caught them. The 4 real survivors stay in the denominator - each one is a missing test case.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('70% (14 / 20)', false),
        ('77.8% (14 / 18)', true),
        ('80% ((14 + 2) / 20)', false),
        ('88.9% ((14 + 2) / 18)', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_331'), 'Your project runs:

node --test --experimental-test-coverage --test-coverage-lines=90

Which statements are true on Node 24? (Select all that apply.)', 'multiple_choice'::question_type, 'Line coverage counts a line as covered when any part of it ran, so if (coupon.expired) throw new Error(...) on one line is covered by a test that only checks the condition - the throw never ran; branch coverage (and splitting the line) shows it. With --test-coverage-lines=90 the runner prints an error such as "77.78% line coverage does not meet threshold of 90%." and exits with code 1 even when every test passed, which fails the CI step. The report only lists files that were loaded while the tests ran: a source file no test imports does not appear at all, so it cannot drag the percentage down - it is silently missing, not 0%. And coverage records only that code ran; whether an assertion checked the result is invisible to it, which is why a suite of typeof checks can reach 100%.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qaf_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A file can show 100.00 line % while a throw inside it never ran, if the if and the throw are on one line.', true),
        ('If line coverage is below 90%, the run exits with code 1 even when every test passed.', true),
        ('A source file that no test imports is listed with 0.00 line %, so it lowers the total.', false),
        ('100% line coverage means every line''s result was checked by at least one assertion.', false)
    ) AS o(option_text, is_correct);

